// The host has no checkout of this repository, so "is the installed backup what the repo says?"
// (spec 084 FR-004) is answered by a committed checksum list both sides can compute with coreutils:
// infrastructure-as-code/backup/INSTALLED.sha256, regenerated by scripts/backup-install-manifest.mjs.
// A stale list is worse than none: the operator's `sha256sum -c` would pass against an old script.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, writeFileSync, appendFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const SCRIPT = resolve(REPO_ROOT, 'scripts/backup-install-manifest.mjs');
const BACKUP_DIR = resolve(REPO_ROOT, 'infrastructure-as-code/backup');

const run = (args) => spawnSync(process.execPath, [SCRIPT, ...args], { encoding: 'utf8' });

/** A copy of the backup directory the cases can corrupt. */
function scratchCopy() {
  const d = join(mkdtempSync(join(tmpdir(), 'backup-manifest-')), 'backup');
  cpSync(BACKUP_DIR, d, { recursive: true });
  return d;
}

test('the committed INSTALLED.sha256 matches the scripts and units in the directory', () => {
  const r = run(['--check']);
  assert.equal(r.status, 0, `${r.stdout}${r.stderr}`);
});

test('every installable file is listed at its HOME-relative install path', () => {
  const lines = readFileSync(join(BACKUP_DIR, 'INSTALLED.sha256'), 'utf8').trim().split('\n');
  const paths = lines.map((l) => l.split(/\s+/)[1]);
  assert.ok(paths.includes('backup/backup.sh'));
  assert.ok(paths.includes('.config/systemd/user/homelab-backup.service'));
  assert.ok(paths.includes('.config/systemd/user/homelab-backup.timer'));
  assert.deepEqual(paths, [...paths].sort(), 'sorted, so a regenerated list diffs cleanly');
  for (const l of lines) assert.match(l, /^[0-9a-f]{64} {2}\S+$/, `sha256sum -c format: ${l}`);
});

test('--check fails, naming the file, when a listed file changed', () => {
  const d = scratchCopy();
  appendFileSync(join(d, 'backup.sh'), '# drift\n');
  const r = run(['--check', '--dir', d]);
  assert.equal(r.status, 1);
  assert.match(r.stdout + r.stderr, /backup\/backup\.sh/);
});

test('--check fails when a new installable file is not listed, or a listed one is gone', () => {
  const d = scratchCopy();
  writeFileSync(join(d, 'extra.timer'), '[Timer]\n');
  let r = run(['--check', '--dir', d]);
  assert.equal(r.status, 1);
  assert.match(r.stdout + r.stderr, /extra\.timer/);

  const e = scratchCopy();
  writeFileSync(join(e, 'INSTALLED.sha256'),
    readFileSync(join(e, 'INSTALLED.sha256'), 'utf8') + `${'0'.repeat(64)}  backup/gone.sh\n`);
  r = run(['--check', '--dir', e]);
  assert.equal(r.status, 1);
  assert.match(r.stdout + r.stderr, /gone\.sh/);
});

test('--write regenerates a list that --check then accepts', () => {
  const d = scratchCopy();
  appendFileSync(join(d, 'backup.sh'), '# changed\n');
  assert.equal(run(['--write', '--dir', d]).status, 0);
  assert.equal(run(['--check', '--dir', d]).status, 0);
});

test('a missing mode or an unknown argument is rejected before anything is written', () => {
  for (const args of [[], ['--dry-run'], ['--check', '--write'], ['--write', 'extra']]) {
    const r = run(args);
    assert.equal(r.status, 2, `args ${JSON.stringify(args)} must exit 2, got ${r.status}`);
  }
});

test('--help prints usage naming every flag, and does nothing else', () => {
  const d = scratchCopy();
  writeFileSync(join(d, 'INSTALLED.sha256'), 'sentinel\n');
  const r = run(['--help', '--write', '--dir', d]);
  assert.equal(r.status, 0);
  for (const flag of ['--check', '--write', '--dir']) assert.match(r.stdout, new RegExp(flag));
  assert.equal(readFileSync(join(d, 'INSTALLED.sha256'), 'utf8'), 'sentinel\n');
});
